import { getSupabaseClient } from "../supabase/supabaseClient";

export type PublisherEarningsCurrencyBalance = Readonly<{
  currency: string;
  pending_balance_minor: number;
  available_balance_minor: number;
  paid_balance_minor: number;
  refunded_or_reversed_minor: number;
  gross_revenue_minor: number;
  net_revenue_minor: number;
  subscriptions_net_minor: number;
  donations_net_minor: number;
  ads_net_minor: number;
}>;

export type PublisherEarningsOverview = Readonly<{
  ok: boolean;
  publisher_user_id?: string;
  payouts_available: boolean;
  payouts_status: string;
  balances_by_currency: ReadonlyArray<PublisherEarningsCurrencyBalance>;
  note?: string;
}>;

export type PublisherFinanceTransaction = Readonly<{
  id: string;
  created_at: string;
  source_type: string;
  entry_type: string;
  amount_minor: number;
  currency: string;
  direction: string;
  balance_bucket: string;
  status: string;
  correlation_id: string;
}>;

type RpcClient = {
  rpc: (
    fn: string,
    args?: Record<string, unknown>,
  ) => Promise<{ data: unknown; error: { message: string } | null }>;
};

function client(): RpcClient | null {
  return getSupabaseClient() as unknown as RpcClient | null;
}

function asOverview(data: unknown): PublisherEarningsOverview {
  const row = (data ?? {}) as Partial<PublisherEarningsOverview>;
  return {
    ok: Boolean(row.ok),
    publisher_user_id: row.publisher_user_id,
    payouts_available: false,
    payouts_status: row.payouts_status ?? "PAYOUTS_NOT_IMPLEMENTED",
    balances_by_currency: Array.isArray(row.balances_by_currency)
      ? (row.balances_by_currency as PublisherEarningsCurrencyBalance[])
      : [],
    note: row.note,
  };
}

/** Format integer minor units without floating money math. */
export function formatMinorUnits(amountMinor: number, currency: string, locale: string): string {
  const safe = Number.isFinite(amountMinor) ? Math.trunc(amountMinor) : 0;
  const code = (currency || "EUR").toUpperCase();
  try {
    const fractionDigits =
      new Intl.NumberFormat("en", { style: "currency", currency: code }).resolvedOptions()
        .maximumFractionDigits ?? 2;
    const divisor = 10 ** fractionDigits;
    return new Intl.NumberFormat(locale, {
      style: "currency",
      currency: code,
      currencyDisplay: "symbol",
    }).format(safe / divisor);
  } catch {
    return `${safe} ${code} (minor)`;
  }
}

export const publisherMonetizationService = {
  async getEarningsOverview(): Promise<{ ok: true; data: PublisherEarningsOverview } | { ok: false; error: string }> {
    const supabase = client();
    if (!supabase) return { ok: false, error: "SUPABASE_UNAVAILABLE" };
    const { data, error } = await supabase.rpc("get_publisher_earnings_overview", {
      p_include_internal_test: false,
    });
    if (error) return { ok: false, error: error.message };
    return { ok: true, data: asOverview(data) };
  },

  async getTransactions(params?: {
    limit?: number;
    offset?: number;
    sourceType?: string;
    currency?: string;
  }): Promise<{ ok: true; items: PublisherFinanceTransaction[] } | { ok: false; error: string }> {
    const supabase = client();
    if (!supabase) return { ok: false, error: "SUPABASE_UNAVAILABLE" };
    const { data, error } = await supabase.rpc("get_publisher_transactions", {
      p_limit: params?.limit ?? 50,
      p_offset: params?.offset ?? 0,
      p_source_type: params?.sourceType ?? null,
      p_currency: params?.currency ?? null,
      p_include_internal_test: false,
    });
    if (error) return { ok: false, error: error.message };
    const payload = (data ?? {}) as { items?: PublisherFinanceTransaction[] };
    return { ok: true, items: Array.isArray(payload.items) ? payload.items : [] };
  },

  async getRevenueTimeseries(params?: {
    bucket?: "day" | "week" | "month";
    currency?: string;
  }): Promise<{ ok: true; series: unknown[] } | { ok: false; error: string }> {
    const supabase = client();
    if (!supabase) return { ok: false, error: "SUPABASE_UNAVAILABLE" };
    const { data, error } = await supabase.rpc("get_publisher_revenue_timeseries", {
      p_bucket: params?.bucket ?? "day",
      p_currency: params?.currency ?? null,
      p_include_internal_test: false,
    });
    if (error) return { ok: false, error: error.message };
    const payload = (data ?? {}) as { series?: unknown[] };
    return { ok: true, series: Array.isArray(payload.series) ? payload.series : [] };
  },

  async getSubscriptionMetrics(): Promise<{ ok: true; data: unknown } | { ok: false; error: string }> {
    const supabase = client();
    if (!supabase) return { ok: false, error: "SUPABASE_UNAVAILABLE" };
    const { data, error } = await supabase.rpc("get_publisher_subscription_metrics", {
      p_include_internal_test: false,
    });
    if (error) return { ok: false, error: error.message };
    return { ok: true, data };
  },
};

import { useEffect, useState } from "react";
import { localizationService } from "../../services/localizationService";
import {
  formatMinorUnits,
  publisherMonetizationService,
  type PublisherEarningsOverview,
  type PublisherFinanceTransaction,
} from "../../services/live/publisherMonetizationService";
import { featureFlagService } from "../../services/featureFlagService";
import { translatePublisherMonetization } from "../../services/localization/publisherMonetizationCatalog";

type SubSection = "overview" | "subscriptions" | "donations" | "ads" | "transactions";

function t(key: string): string {
  return translatePublisherMonetization(key, localizationService.getLanguage());
}

export function PublisherEarningsPanel() {
  const enabled = featureFlagService.isEnabled("enablePublisherEarningsDashboard");
  const locale = localizationService.getLanguage();
  const [section, setSection] = useState<SubSection>("overview");
  const [overview, setOverview] = useState<PublisherEarningsOverview | null>(null);
  const [transactions, setTransactions] = useState<ReadonlyArray<PublisherFinanceTransaction>>([]);
  const [error, setError] = useState<string | null>(null);
  const [sourceFilter, setSourceFilter] = useState("");

  useEffect(() => {
    if (!enabled) return;
    let cancelled = false;
    void (async () => {
      const result = await publisherMonetizationService.getEarningsOverview();
      if (cancelled) return;
      if (!result.ok) {
        setError(result.error);
        return;
      }
      setOverview(result.data);
      setError(null);
    })();
    return () => {
      cancelled = true;
    };
  }, [enabled]);

  useEffect(() => {
    if (!enabled || section !== "transactions") return;
    let cancelled = false;
    void (async () => {
      const result = await publisherMonetizationService.getTransactions({
        limit: 40,
        sourceType: sourceFilter || undefined,
      });
      if (cancelled) return;
      if (!result.ok) {
        setError(result.error);
        return;
      }
      setTransactions(result.items);
    })();
    return () => {
      cancelled = true;
    };
  }, [enabled, section, sourceFilter]);

  if (!enabled) {
    return (
      <div className="publisher-card" role="status">
        <h2>{t("earnings.title")}</h2>
        <p>{t("earnings.monetizationUnavailable")}</p>
      </div>
    );
  }

  const balances = overview?.balances_by_currency ?? [];

  return (
    <section className="publisher-card" aria-label={t("earnings.aria")}>
      <header>
        <h2>{t("earnings.title")}</h2>
        <p role="status">{t("earnings.payoutsUnavailable")}</p>
        <p>{t("earnings.payoutSetupUnavailable")}</p>
      </header>

      <nav className="publisher-tabs" aria-label={t("earnings.title")}>
        {(
          [
            ["overview", "earnings.overview"],
            ["subscriptions", "earnings.subscriptions"],
            ["donations", "earnings.donations"],
            ["ads", "earnings.adRevenue"],
            ["transactions", "earnings.transactions"],
          ] as const
        ).map(([key, label]) => (
          <button
            key={key}
            type="button"
            className={section === key ? "is-active" : ""}
            onClick={() => setSection(key)}
          >
            {t(label)}
          </button>
        ))}
      </nav>

      {error ? <p className="publisher-error" role="alert">{error}</p> : null}

      {section === "overview" ? (
        <div>
          <h3>{t("earnings.revenueBreakdown")}</h3>
          {balances.length === 0 ? <p>{t("earnings.empty")}</p> : null}
          <table aria-label={t("earnings.tableFallback")}>
            <thead>
              <tr>
                <th scope="col">{t("earnings.currency")}</th>
                <th scope="col">{t("earnings.pendingBalance")}</th>
                <th scope="col">{t("earnings.availableBalance")}</th>
                <th scope="col">{t("earnings.paidOut")}</th>
                <th scope="col">{t("earnings.grossRevenue")}</th>
                <th scope="col">{t("earnings.netRevenue")}</th>
                <th scope="col">{t("earnings.refund")}</th>
              </tr>
            </thead>
            <tbody>
              {balances.map((row) => (
                <tr key={row.currency}>
                  <td>{row.currency}</td>
                  <td>
                    <span aria-label={`${t("earnings.pendingBalance")} ${row.currency}`}>
                      {formatMinorUnits(row.pending_balance_minor, row.currency, locale)}
                    </span>
                  </td>
                  <td>
                    <span aria-label={`${t("earnings.availableBalance")} ${row.currency}`}>
                      {formatMinorUnits(row.available_balance_minor, row.currency, locale)}
                    </span>
                  </td>
                  <td>
                    <span aria-label={`${t("earnings.paidOut")} ${row.currency}`}>
                      {formatMinorUnits(row.paid_balance_minor, row.currency, locale)}
                    </span>
                    <span> — {t("earnings.payoutsUnavailable")}</span>
                  </td>
                  <td>{formatMinorUnits(row.gross_revenue_minor, row.currency, locale)}</td>
                  <td>{formatMinorUnits(row.net_revenue_minor, row.currency, locale)}</td>
                  <td>
                    <span aria-label={`${t("earnings.refund")} / ${t("earnings.chargeback")}`}>
                      {formatMinorUnits(Math.abs(row.refunded_or_reversed_minor), row.currency, locale)}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <ul aria-label={t("earnings.revenueBreakdown")}>
            {balances.map((row) => (
              <li key={`${row.currency}-break`}>
                {row.currency}: {t("earnings.subscriptions")}{" "}
                {formatMinorUnits(row.subscriptions_net_minor, row.currency, locale)};{" "}
                {t("earnings.donations")} {formatMinorUnits(row.donations_net_minor, row.currency, locale)};{" "}
                {t("earnings.adRevenue")} {formatMinorUnits(row.ads_net_minor, row.currency, locale)}
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      {section === "subscriptions" ? (
        <div>
          <h3>{t("earnings.subscriptions")}</h3>
          <p>{t("earnings.monetizationUnavailable")}</p>
          <p>{t("earnings.subscriptionTier")}: {t("earnings.monthly")} / {t("earnings.yearly")}</p>
        </div>
      ) : null}

      {section === "donations" ? (
        <div>
          <h3>{t("earnings.donations")}</h3>
          <p>{t("earnings.tips")}</p>
          <p>{t("earnings.monetizationUnavailable")}</p>
        </div>
      ) : null}

      {section === "ads" ? (
        <div>
          <h3>{t("earnings.adRevenue")}</h3>
          <p>{t("earnings.monetizationUnavailable")}</p>
        </div>
      ) : null}

      {section === "transactions" ? (
        <div>
          <h3>{t("earnings.transactions")}</h3>
          <div role="group" aria-label={t("earnings.filters")}>
            <label>
              {t("earnings.source")}
              <select value={sourceFilter} onChange={(event) => setSourceFilter(event.target.value)}>
                <option value="">—</option>
                <option value="subscription">{t("earnings.subscriptions")}</option>
                <option value="donation">{t("earnings.donations")}</option>
                <option value="ad_revenue">{t("earnings.adRevenue")}</option>
                <option value="refund">{t("earnings.refund")}</option>
                <option value="chargeback">{t("earnings.chargeback")}</option>
              </select>
            </label>
          </div>
          <table aria-label={t("earnings.transactions")}>
            <thead>
              <tr>
                <th scope="col">{t("earnings.date")}</th>
                <th scope="col">{t("earnings.source")}</th>
                <th scope="col">{t("earnings.net")}</th>
                <th scope="col">{t("earnings.currency")}</th>
                <th scope="col">{t("earnings.status")}</th>
              </tr>
            </thead>
            <tbody>
              {transactions.map((tx) => (
                <tr key={tx.id}>
                  <td>{new Date(tx.created_at).toLocaleString(locale)}</td>
                  <td>{tx.source_type}</td>
                  <td>
                    <span>
                      {tx.direction === "debit" ? "−" : "+"}
                      {formatMinorUnits(tx.amount_minor, tx.currency, locale)}
                    </span>
                  </td>
                  <td>{tx.currency}</td>
                  <td>{tx.balance_bucket}</td>
                </tr>
              ))}
              {transactions.length === 0 ? (
                <tr>
                  <td colSpan={5}>{t("earnings.empty")}</td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>
      ) : null}
    </section>
  );
}

﻿import { appConfig } from "../config/appConfig";
import { loggingService } from "./loggingService";

export const FEATURE_FLAG_KEYS = [
  "enableRealtime",
  "enableVoiceRooms",
  "enableScreenShare",
  "enableDirectMessages",
  "enableFriends",
  "enableDiscovery",
  "enableBots",
  "enableWebhooks",
  "enableThreads",
  "enablePolls",
  "enableAdvancedModeration",
  "enableDiagnostics",
  "enableAutoUpdate",
  "enableAnalyticsPlaceholder",
  "enableAdminOperations",
  "enableDeveloperPortal",
  "enableCustomEmoji",
  "enableStickers",
  "enableForumChannels",
  "enableAnnouncementChannels",
  "enableSavedMessages",
  "enableOnboardingExperiment",
  "enablePublisherApplication",
  "enablePublisherReview",
  "enablePublisherBadgeDisplay",
  "enableLiveNowDiscovery",
  "enableGoLive",
  "enablePublisherReminders",
  "enablePublisherNotificationPreferences",
  "enablePublisherStreamManagement",
  "enablePublisherExternalIngest",
  "enableLiveChat",
  "enableLiveModeration",
  "enableHavoocSupportHub",
  "enablePublisherAnalytics",
  "enableLiveRecording",
  "enableLiveReplays",
  "enableLiveClips",
  "enablePublisherMonetization",
  "enablePublisherSubscriptions",
  "enablePublisherDonations",
  "enablePublisherAdRevenue",
  "enablePublisherEarningsDashboard",
] as const;

export type FeatureFlagKey = (typeof FEATURE_FLAG_KEYS)[number];
export type FeatureFlags = Readonly<Record<FeatureFlagKey, boolean>>;
export type FeatureFlagOverrides = Partial<Record<FeatureFlagKey, boolean>>;
export type FeatureFlagSource = "defaults" | "environment" | "remote" | "runtime";

export const PRODUCTION_FEATURE_FLAGS = Object.freeze({
  voice: "enableVoiceRooms",
  screenShare: "enableScreenShare",
  webhooks: "enableWebhooks",
  bots: "enableBots",
  discovery: "enableDiscovery",
  adminOperations: "enableAdminOperations",
  autoUpdate: "enableAutoUpdate",
  analytics: "enableAnalyticsPlaceholder",
  publisherApplication: "enablePublisherApplication",
  publisherReview: "enablePublisherReview",
  publisherBadgeDisplay: "enablePublisherBadgeDisplay",
  liveNowDiscovery: "enableLiveNowDiscovery",
  goLive: "enableGoLive",
  publisherReminders: "enablePublisherReminders",
  publisherNotificationPreferences: "enablePublisherNotificationPreferences",
  publisherStreamManagement: "enablePublisherStreamManagement",
  publisherExternalIngest: "enablePublisherExternalIngest",
  liveChat: "enableLiveChat",
  liveModeration: "enableLiveModeration",
  havoocSupportHub: "enableHavoocSupportHub",
  publisherAnalytics: "enablePublisherAnalytics",
  liveRecording: "enableLiveRecording",
  liveReplays: "enableLiveReplays",
  liveClips: "enableLiveClips",
  publisherMonetization: "enablePublisherMonetization",
  publisherSubscriptions: "enablePublisherSubscriptions",
  publisherDonations: "enablePublisherDonations",
  publisherAdRevenue: "enablePublisherAdRevenue",
  publisherEarningsDashboard: "enablePublisherEarningsDashboard",
} as const satisfies Record<string, FeatureFlagKey>);

export type FeatureFlagSnapshot = Readonly<{
  flags: FeatureFlags;
  sources: Partial<Record<FeatureFlagKey, FeatureFlagSource>>;
  updatedAt: string;
}>;

export type FeatureAvailability = Readonly<{
  key: FeatureFlagKey;
  enabled: boolean;
  reason?: string;
}>;

type FeatureFlagListener = (snapshot: FeatureFlagSnapshot) => void;

const keySet = new Set<string>(FEATURE_FLAG_KEYS);
const listeners = new Set<FeatureFlagListener>();
let remoteOverrides: FeatureFlagOverrides = {};
let runtimeOverrides: FeatureFlagOverrides = {};

function createDefaultFeatureFlags(): FeatureFlags {
  const developmentDiagnostics = appConfig.environment !== "production";

  return Object.freeze({
    enableRealtime: true,
    enableVoiceRooms: true,
    enableScreenShare: true,
    enableDirectMessages: false,
    enableFriends: false,
    enableDiscovery: false,
    enableBots: false,
    enableWebhooks: false,
    enableThreads: true,
    enablePolls: true,
    enableAdvancedModeration: false,
    enableDiagnostics: developmentDiagnostics,
    enableAutoUpdate: false,
    enableAnalyticsPlaceholder: false,
    enableAdminOperations: false,
    enableDeveloperPortal: false,
    enableCustomEmoji: false,
    enableStickers: false,
    enableForumChannels: false,
    enableAnnouncementChannels: false,
    enableSavedMessages: true,
    enableOnboardingExperiment: false,
    // Publisher/Creator Phase 1 production defaults: fail-closed until controlled enablement.
    enablePublisherApplication: appConfig.environment !== "production",
    enablePublisherReview: appConfig.environment !== "production",
    enablePublisherBadgeDisplay: appConfig.environment !== "production",
    enableLiveNowDiscovery: appConfig.environment !== "production",
    enableGoLive: appConfig.environment !== "production",
    enablePublisherReminders: appConfig.environment !== "production",
    enablePublisherNotificationPreferences: appConfig.environment !== "production",
    enablePublisherStreamManagement: appConfig.environment !== "production",
    enablePublisherExternalIngest: appConfig.environment !== "production",
    enableLiveChat: appConfig.environment !== "production",
    enableLiveModeration: appConfig.environment !== "production",
    // HAVOOC Support Hub: fail-closed in production until controlled enablement.
    enableHavoocSupportHub: appConfig.environment !== "production",
    enablePublisherAnalytics: appConfig.environment !== "production",
    enableLiveRecording: appConfig.environment !== "production",
    enableLiveReplays: appConfig.environment !== "production",
    enableLiveClips: appConfig.environment !== "production",
    // Monetization: fail-closed until provider/legal/payout gates certified.
    enablePublisherMonetization: appConfig.environment !== "production",
    enablePublisherSubscriptions: appConfig.environment !== "production",
    enablePublisherDonations: appConfig.environment !== "production",
    enablePublisherAdRevenue: appConfig.environment !== "production",
    enablePublisherEarningsDashboard: appConfig.environment !== "production",
  });
}

function isFeatureFlagKey(value: string): value is FeatureFlagKey {
  return keySet.has(value);
}

function parseBooleanFlag(value: unknown): boolean | null {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value !== "string") {
    return null;
  }

  const normalized = value.trim().toLowerCase();
  if (["1", "true", "on", "enabled", "yes"].includes(normalized)) {
    return true;
  }

  if (["0", "false", "off", "disabled", "no"].includes(normalized)) {
    return false;
  }

  return null;
}

function sanitizeOverrides(input: unknown, source: FeatureFlagSource): FeatureFlagOverrides {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return {};
  }

  const next: FeatureFlagOverrides = {};
  for (const [key, value] of Object.entries(input)) {
    if (!isFeatureFlagKey(key)) {
      loggingService.logWarn("Ignoring unknown feature flag key", { key, source }, "feature-flags");
      continue;
    }

    const parsed = parseBooleanFlag(value);
    if (parsed === null) {
      loggingService.logWarn("Ignoring invalid feature flag value", { key, source }, "feature-flags");
      continue;
    }

    next[key] = parsed;
  }

  return next;
}

function parseDelimitedOverrides(raw: string): FeatureFlagOverrides {
  const entries: Record<string, string> = {};
  for (const part of raw.split(/[;,]/)) {
    const [rawKey, ...rawValue] = part.split("=");
    const key = rawKey?.trim();
    const value = rawValue.join("=").trim();
    if (key && value) {
      entries[key] = value;
    }
  }

  return sanitizeOverrides(entries, "environment");
}

function parseEnvironmentOverrides(): FeatureFlagOverrides {
  const rawValue = import.meta.env.VITE_FEATURE_FLAGS;
  if (typeof rawValue !== "string" || rawValue.trim().length === 0) {
    return {};
  }

  const raw = rawValue.trim();
  if (raw.startsWith("{")) {
    try {
      return sanitizeOverrides(JSON.parse(raw) as unknown, "environment");
    } catch (error) {
      loggingService.logWarn("Failed to parse VITE_FEATURE_FLAGS JSON", { error }, "feature-flags");
      return {};
    }
  }

  return parseDelimitedOverrides(raw);
}

function createSnapshot(): FeatureFlagSnapshot {
  const defaults = createDefaultFeatureFlags();
  const envOverrides = parseEnvironmentOverrides();
  const flags = {
    ...defaults,
    ...envOverrides,
    ...remoteOverrides,
    ...runtimeOverrides,
  } satisfies Record<FeatureFlagKey, boolean>;

  const sources: Partial<Record<FeatureFlagKey, FeatureFlagSource>> = {};
  for (const key of FEATURE_FLAG_KEYS) {
    if (key in runtimeOverrides) {
      sources[key] = "runtime";
    } else if (key in remoteOverrides) {
      sources[key] = "remote";
    } else if (key in envOverrides) {
      sources[key] = "environment";
    } else {
      sources[key] = "defaults";
    }
  }

  return Object.freeze({
    flags: Object.freeze(flags),
    sources: Object.freeze(sources),
    updatedAt: new Date().toISOString(),
  });
}

function emitSnapshot(): FeatureFlagSnapshot {
  const snapshot = createSnapshot();
  for (const listener of listeners) {
    listener(snapshot);
  }

  return snapshot;
}

export const featureFlagService = {
  keys: FEATURE_FLAG_KEYS,

  getDefaultFeatureFlags(): FeatureFlags {
    return createDefaultFeatureFlags();
  },

  getSnapshot(): FeatureFlagSnapshot {
    return createSnapshot();
  },

  getFlags(): FeatureFlags {
    return createSnapshot().flags;
  },

  isEnabled(key: FeatureFlagKey): boolean {
    return createSnapshot().flags[key];
  },

  getAvailability(key: FeatureFlagKey): FeatureAvailability {
    const enabled = this.isEnabled(key);
    return {
      key,
      enabled,
      reason: enabled ? undefined : "This feature is currently unavailable in this Picom build.",
    };
  },

  shouldShowEntryPoint(key: FeatureFlagKey): boolean {
    return this.isEnabled(key);
  },

  applyRemoteConfig(input: unknown): FeatureFlagSnapshot {
    remoteOverrides = sanitizeOverrides(input, "remote");
    return emitSnapshot();
  },

  clearRemoteConfig(): FeatureFlagSnapshot {
    remoteOverrides = {};
    return emitSnapshot();
  },

  setRuntimeOverride(key: FeatureFlagKey, enabled: boolean): FeatureFlagSnapshot {
    if (appConfig.environment === "production") {
      loggingService.logWarn("Runtime feature flag override ignored in production", { key }, "feature-flags");
      return createSnapshot();
    }

    runtimeOverrides = {
      ...runtimeOverrides,
      [key]: enabled,
    };
    return emitSnapshot();
  },

  clearRuntimeOverrides(): FeatureFlagSnapshot {
    runtimeOverrides = {};
    return emitSnapshot();
  },

  subscribe(listener: FeatureFlagListener): () => void {
    listeners.add(listener);
    return () => {
      listeners.delete(listener);
    };
  },
};

import { useEffect, useState } from "react";
import { localizationService } from "../../services/localizationService";
import {
  translatePublisherProgram,
  type PublisherProgramI18nKey,
} from "../../services/localization/publisherProgramCatalog";
import { publisherProgramService } from "../../services/publisher/publisherProgramService";
import type { PublisherProgramState } from "../../services/publisher/publisherProgramTypes";
import { featureFlagService } from "../../services/featureFlagService";
import { getSupabaseClient } from "../../services/supabase/supabaseClient";
import { PublisherStreamsWorkspace } from "./PublisherStreamsWorkspace";
import { PublisherAnalyticsPanel } from "./PublisherAnalyticsPanel";
import { PublisherReplayArchivePanel } from "./PublisherReplayArchivePanel";
import { PublisherEarningsPanel } from "./PublisherEarningsPanel";
