type Props = Readonly<{
  onClose: () => void;
  onGoLive: () => void;
  onOpenApplication: () => void;
}>;

type ScheduleRow = {
  id: string;
  title: string;
  status: string;
  scheduled_start_at: string;
  stream_type: string;
};

function t(key: PublisherProgramI18nKey, params?: Record<string, string | number>): string {
  return translatePublisherProgram(key, localizationService.getLanguage(), params);
}

export function PublisherDashboardWorkspace({ onClose, onGoLive, onOpenApplication }: Props) {
  const streamManagementEnabled = featureFlagService.isEnabled("enablePublisherStreamManagement");
  const analyticsEnabled = featureFlagService.isEnabled("enablePublisherAnalytics");
  const replaysEnabled = featureFlagService.isEnabled("enableLiveReplays");
  const earningsEnabled = featureFlagService.isEnabled("enablePublisherEarningsDashboard");
  const [state, setState] = useState<PublisherProgramState | null>(null);
  const [schedules, setSchedules] = useState<ScheduleRow[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [title, setTitle] = useState("");
  const [startAt, setStartAt] = useState("");
  const [section, setSection] = useState<"overview" | "streams" | "analytics" | "archive" | "earnings" | "create" | "schedule" | "settings">("overview");

  async function refresh() {
    const program = await publisherProgramService.getProgramState();
    if (!program.ok) {
      setError(program.error);
      setState(null);
      return;
    }
    setState(program.data);
    setError(null);
    const client = getSupabaseClient() as unknown as {
      from: (table: string) => {
        select: (cols: string) => {
          order: (col: string, opts: { ascending: boolean }) => {
            limit: (n: number) => Promise<{ data: ScheduleRow[] | null }>;
          };
        };
        insert: (row: Record<string, unknown>) => Promise<{ error: { message: string } | null }>;
      };
      auth: { getSession: () => Promise<{ data: { session: { user: { id: string } } | null } }> };
    } | null;
    if (!client || !program.data.canBroadcast) {
      setSchedules([]);
      return;
    }
    const { data } = await client
      .from("publisher_stream_schedules")
      .select("id,title,status,scheduled_start_at,stream_type")
      .order("scheduled_start_at", { ascending: true })
      .limit(40);
    setSchedules(data ?? []);
  }

  useEffect(() => {
    void refresh();
  }, []);

  async function createSchedule() {
    if (!state?.canBroadcast) return;
    const client = getSupabaseClient() as unknown as {
      from: (table: string) => {
        insert: (row: Record<string, unknown>) => Promise<{ error: { message: string } | null }>;
      };
      auth: { getSession: () => Promise<{ data: { session: { user: { id: string } } | null } }> };
    } | null;
    if (!client) return;
    const { data: session } = await client.auth.getSession();
    const userId = session.session?.user?.id;
    if (!userId || !title.trim() || !startAt) return;
    const { error: insertError } = await client.from("publisher_stream_schedules").insert({
      owner_user_id: userId,
      title: title.trim(),
      scheduled_start_at: new Date(startAt).toISOString(),
      status: "scheduled",
      visibility: "public",
      stream_type: "screen_share",
    });
    if (insertError) {
      setError(insertError.message);
      return;
    }
    setTitle("");
    setStartAt("");
    await refresh();
  }

  const tabLabel: Record<Exclude<typeof section, "analytics" | "archive" | "earnings">, PublisherProgramI18nKey> = {
    overview: "dash.tab.overview",
    streams: "dash.tab.streams",
    create: "dash.tab.create",
    schedule: "dash.tab.schedule",
    settings: "dash.tab.settings",
  };

  if (state && !state.canBroadcast) {
    return (
      <section className="publisher-program-shell">
        <header className="publisher-program-header">
          <div>
            <h1>{t("dash.title")}</h1>
            <p>{t("dash.gatedBody")}</p>
          </div>
          <button type="button" className="publisher-ghost" onClick={onClose}>{t("dash.close")}</button>
        </header>
        <div className="publisher-card">
          <p>{t("dash.noBroadcast")}</p>
          <button type="button" className="publisher-primary" onClick={onOpenApplication}>{t("dash.viewApplication")}</button>
        </div>
      </section>
    );
  }

  return (
    <section className="publisher-program-shell" aria-label={t("dash.aria")}>
      <header className="publisher-program-header">
        <div>
          <p className="publisher-eyebrow">{t("dash.eyebrow")}</p>
          <h1>{state?.profile?.displayPublisherName || t("dash.fallbackName")}</h1>
          <p>
            {state?.activeBadge
              ? t("dash.badgeActive", { type: state.activeBadge.badgeType })
              : t("dash.badgeLoading")}
          </p>
        </div>
        <div className="publisher-header-actions">
          <button type="button" className="publisher-primary" onClick={onGoLive}>{t("dash.goLive")}</button>
          <button type="button" className="publisher-ghost" onClick={onClose}>{t("dash.close")}</button>
        </div>
      </header>

      <nav className="publisher-tabs" aria-label={t("dash.tabsAria")}>
        {(["overview", "streams", ...(analyticsEnabled ? (["analytics"] as const) : []), ...(replaysEnabled ? (["archive"] as const) : []), ...(earningsEnabled ? (["earnings"] as const) : []), "create", "schedule", "settings"] as const).map((key) => (
          <button key={key} type="button" className={section === key ? "is-active" : ""} onClick={() => setSection(key)}>
            {key === "analytics"
              ? translatePublisherAnalytics("analytics.title", localizationService.getLanguage())
              : key === "archive"
                ? translatePublisherMedia("media.archive", localizationService.getLanguage())
              : key === "earnings"
                ? translatePublisherMonetization("earnings.title", localizationService.getLanguage())
              : t(tabLabel[key])}
          </button>
        ))}
      </nav>

      {error ? <p className="publisher-error" role="alert">{error}</p> : null}

      {section === "overview" ? (
        <div className="publisher-card">
          <h2>{t("dash.overviewTitle")}</h2>
          <p>{t("dash.overviewBody")}</p>
          <p>{t("dash.overviewBilling")}</p>
        </div>
      ) : null}

      {section === "analytics" && analyticsEnabled ? <PublisherAnalyticsPanel /> : null}
      {section === "archive" && replaysEnabled ? <PublisherReplayArchivePanel /> : null}
      {section === "earnings" && earningsEnabled ? <PublisherEarningsPanel /> : null}

      {section === "streams" && streamManagementEnabled ? (
        <PublisherStreamsWorkspace onGoLive={onGoLive} />
      ) : null}

      {(section === "streams" && !streamManagementEnabled) || section === "schedule" ? (
        <div className="publisher-card">
          <h2>{t("dash.scheduleTitle")}</h2>
          <ul className="publisher-list">
            {schedules.map((row) => (
              <li key={row.id}>
                <strong>{row.title}</strong> · {row.status} · {new Date(row.scheduled_start_at).toLocaleString()} · {row.stream_type}
              </li>
            ))}
            {schedules.length === 0 ? <li>{t("dash.scheduleEmpty")}</li> : null}
          </ul>
        </div>
      ) : null}

      {section === "create" ? (
        <form
          className="publisher-card publisher-form"
          onSubmit={(event) => {
            event.preventDefault();
            void createSchedule();
          }}
        >
          <h2>{t("dash.planTitle")}</h2>
          <label>
            {t("dash.planName")}
            <input value={title} onChange={(event) => setTitle(event.target.value)} required minLength={2} maxLength={160} />
          </label>
          <label>
            {t("dash.planStart")}
            <input type="datetime-local" value={startAt} onChange={(event) => setStartAt(event.target.value)} required />
          </label>
          <button type="submit" className="publisher-primary">{t("dash.planSubmit")}</button>
        </form>
      ) : null}

      {section === "settings" ? (
        <div className="publisher-card">
          <h2>{t("dash.settingsTitle")}</h2>
          <p>{t("dash.accountKind", { kind: state?.profile?.accountKind ?? "—" })}</p>
          <p>{t("dash.profileStatus", { status: state?.profile?.status ?? "—" })}</p>
          <button type="button" className="publisher-ghost" onClick={onOpenApplication}>{t("dash.applicationHistory")}</button>
        </div>
      ) : null}
    </section>
  );
}

/**
 * Provider-neutral payment webhook + checkout gate.
 * Fail-closed when PAYMENT_PROVIDER_* secrets are absent.
 * Never trusts client amounts. Never logs secrets.
 */
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { handleCorsPreflight } from "../_shared/cors.ts";
import { errorResponse, jsonResponse, methodNotAllowed } from "../_shared/http.ts";
import { requireSupabaseUser } from "../_shared/auth.ts";
import { readBoundedJsonObject } from "../_shared/request.ts";

const env = (name: string): string | null => Deno.env.get(name)?.trim() || null;

type ProviderRuntime =
  | { ok: true; provider: string; environment: "TEST" | "LIVE" | "UNKNOWN" }
  | { ok: false; code: string; message: string };

function paymentProviderRuntime(): ProviderRuntime {
  const provider = env("PAYMENT_PROVIDER");
  const secret = env("PAYMENT_PROVIDER_SECRET");
  const webhookSecret = env("PAYMENT_WEBHOOK_SECRET");
  const paymentEnv = (env("PAYMENT_ENV") || "UNKNOWN").toUpperCase();

  if (!provider) {
    return { ok: false, code: "BLOCKED_PROVIDER_CONFIGURATION", message: "PAYMENT_PROVIDER is not configured." };
  }
  if (!secret || !webhookSecret) {
    return {
      ok: false,
      code: "BLOCKED_PROVIDER_CONFIGURATION",
      message: "Payment provider secrets are not configured.",
    };
  }
  const environment = paymentEnv === "TEST" || paymentEnv === "LIVE" ? paymentEnv : "UNKNOWN";
  return { ok: true, provider, environment };
}

function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let out = 0;
  for (let i = 0; i < a.length; i += 1) out |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return out === 0;
}

async function verifyWebhookSignature(request: Request, rawBody: string): Promise<{ ok: true } | { ok: false; reason: string }> {
  const webhookSecret = env("PAYMENT_WEBHOOK_SECRET");
  if (!webhookSecret) return { ok: false, reason: "MISSING_WEBHOOK_SECRET" };

  const signature = request.headers.get("x-picom-payment-signature")
    || request.headers.get("stripe-signature")
    || request.headers.get("x-webhook-signature");
  if (!signature) return { ok: false, reason: "MISSING_SIGNATURE" };

  // Provider-neutral stub: HMAC-SHA256 hex of raw body with webhook secret.
  // Real provider adapters replace this with provider-specific schemes + timestamp tolerance.
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(webhookSecret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const mac = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(rawBody));
  const hex = Array.from(new Uint8Array(mac)).map((b) => b.toString(16).padStart(2, "0")).join("");

  const provided = signature.includes("=")
    ? signature.split(",").map((p) => p.trim()).find((p) => p.startsWith("v1="))?.slice(3) ?? signature
    : signature;

  if (!timingSafeEqual(hex, provided)) {
    return { ok: false, reason: "INVALID_SIGNATURE" };
  }
  return { ok: true };
}

const ALLOWED_EVENTS = new Set([
  "payment.succeeded",
  "payment.failed",
  "subscription.created",
  "subscription.updated",
  "subscription.cancelled",
  "invoice.paid",
  "invoice.failed",
  "refund.created",
  "chargeback.created",
  "chargeback.resolved",
  "account.updated",
]);

Deno.serve(async (request) => {
  const preflight = handleCorsPreflight(request);
  if (preflight) return preflight;

  const url = new URL(request.url);
  const path = url.pathname.replace(/\/+$/, "");

  // Authenticated checkout create — always fail-closed without provider.
  if (path.endsWith("/checkout") && request.method === "POST") {
    const auth = await requireSupabaseUser(request);
    if (!auth.ok) return auth.response;
    const runtime = paymentProviderRuntime();
    if (!runtime.ok) {
      return errorResponse(runtime.code, runtime.message, 503);
    }
    // Provider adapters not activated until credentials + legal gates certified.
    return errorResponse(
      "LIVE_PAYMENT_ACCEPTANCE_OFF",
      "Live payment acceptance is OFF pending business/legal gates.",
      503,
    );
  }

  // Webhook endpoint
  if (path.endsWith("/webhook") && request.method === "POST") {
    const runtime = paymentProviderRuntime();
    if (!runtime.ok) {
      // Ack safely without economic mutation when provider not configured.
      return jsonResponse({ ok: true, ignored: true, reason: runtime.code }, 202);
    }

    const rawBody = await request.text();
    if (rawBody.length > 256_000) {
      return errorResponse("PAYLOAD_TOO_LARGE", "Webhook payload exceeds bound.", 413);
    }

    const verified = await verifyWebhookSignature(request, rawBody);
    if (!verified.ok) {
      return errorResponse("WEBHOOK_AUTH_DENIED", verified.reason, 401);
    }

    let payload: Record<string, unknown>;
    try {
      payload = JSON.parse(rawBody) as Record<string, unknown>;
    } catch {
      return errorResponse("INVALID_JSON", "Webhook body must be JSON.", 400);
    }

    const eventType = String(payload.type || payload.event_type || "");
    const eventId = String(payload.id || payload.event_id || "");
    const eventEnv = payload.environment
      ? String(payload.environment).toUpperCase()
      : payload.livemode === true
        ? "LIVE"
        : payload.livemode === false
          ? "TEST"
          : "UNKNOWN";

    if (runtime.environment !== "UNKNOWN" && eventEnv !== "UNKNOWN" && eventEnv !== runtime.environment) {
      return jsonResponse({ ok: true, ignored: true, reason: "ENVIRONMENT_MISMATCH" }, 202);
    }

    if (!ALLOWED_EVENTS.has(eventType)) {
      return jsonResponse({ ok: true, ignored: true, reason: "UNKNOWN_EVENT" }, 202);
    }

    const supabaseUrl = env("SUPABASE_URL");
    const serviceRole = env("SUPABASE_SERVICE_ROLE_KEY");
    if (!supabaseUrl || !serviceRole) {
      return errorResponse("INTERNAL_ERROR", "Webhook processor is not configured.", 503);
    }

    const operator = createClient(supabaseUrl, serviceRole, {
      auth: { persistSession: false, autoRefreshToken: false },
    });

    // Record idempotent webhook receipt (no secrets / no raw card data).
    const payloadHashBuffer = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(rawBody));
    const payloadHash = Array.from(new Uint8Array(payloadHashBuffer))
      .map((b) => b.toString(16).padStart(2, "0"))
      .join("");

    const { error } = await operator.from("provider_webhook_events").upsert(
      {
        provider: runtime.provider,
        provider_event_id: eventId || payloadHash,
        event_type: eventType,
        payload_hash: payloadHash,
        processing_status: "received",
      },
      { onConflict: "provider,provider_event_id", ignoreDuplicates: true },
    );

    if (error) {
      await operator.from("publisher_finance_event_failures").upsert(
        {
          provider: runtime.provider,
          provider_event_ref: eventId || payloadHash,
          event_type: eventType,
          error_code: "WEBHOOK_PERSIST_FAILED",
          attempts: 1,
          status: "open",
          safe_context: { message: "persist_failed" },
        },
        { onConflict: "provider,provider_event_ref,error_code" },
      );
      return errorResponse("WEBHOOK_PERSIST_FAILED", "Unable to persist webhook event.", 503);
    }

    // Economic mutations require provider adapters mapped to service_record_* functions.
    // Without certified adapters, acknowledge receipt only.
    return jsonResponse({
      ok: true,
      accepted: true,
      economicMutation: false,
      reason: "PROVIDER_ADAPTER_NOT_CERTIFIED",
    });
  }

  if (request.method === "OPTIONS") return preflight ?? jsonResponse({ ok: true });
  if (request.method !== "POST") return methodNotAllowed(["POST", "OPTIONS"]);

  // Default authenticated status probe
  const auth = await requireSupabaseUser(request);
  if (!auth.ok) return auth.response;
  const parsed = await readBoundedJsonObject<{ action?: string }>(request, {
    maxBytes: 2048,
    allowedKeys: new Set(["action"]),
  });
  if (!parsed.ok) return parsed.response;

  const runtime = paymentProviderRuntime();
  return jsonResponse({
    ok: true,
    providerConfigured: runtime.ok,
    code: runtime.ok ? "PROVIDER_PRESENT" : runtime.code,
    liveAcceptance: "OFF",
    publicMonetization: "OFF",
  });
});

﻿import { handleCorsPreflight } from "../_shared/cors.ts";
import { jsonResponse, methodNotAllowed } from "../_shared/http.ts";

function readPublicEnv(name: string, fallback = "", maximumLength = 240): string {
  const value = Deno.env.get(name);
  return value && value.trim().length > 0 ? value.trim().slice(0, maximumLength) : fallback;
}

function readPublicVersion(name: string, fallback: string): string {
  const value = readPublicEnv(name, fallback, 64);
  return /^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$/.test(value) ? value : fallback;
}

function readPublicUrl(name: string): string {
  const value = readPublicEnv(name, "", 2048);
  if (!value) return "";
  try {
    const parsed = new URL(value);
    return parsed.protocol === "https:" || parsed.protocol === "http:" ? parsed.toString() : "";
  } catch {
    return "";
  }
}

function readReleaseChannel(): "dev" | "beta" | "stable" {
  const value = readPublicEnv("PICOM_RELEASE_CHANNEL", "dev");
  return value === "beta" || value === "stable" ? value : "dev";
}

function readMaxUploadBytes(): number {
  const value = Number(readPublicEnv("PICOM_MAX_UPLOAD_BYTES", "10485760"));
  return Number.isFinite(value) && value > 0 ? Math.min(value, 50 * 1024 * 1024) : 10 * 1024 * 1024;
}

function readPublicBooleanEnv(name: string, fallback = false): boolean {
  const value = readPublicEnv(name, fallback ? "true" : "false").toLowerCase();
  return value === "1" || value === "true" || value === "on" || value === "enabled" || value === "yes";
}

